// Replays the cases generated by tools/vsid_v2 (expected SID = v1 reference model) on a v2 config.
// Usage: configcases_test <config_v2.json> <cases.json> [accepted_differences.json]
#include "../sidengine.h"
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <map>
#include <string>
#include <vector>

using namespace vsid::v2;
using Json = nlohmann::ordered_json;

namespace
{
	bool loadJson(const char* path, Json& out)
	{
		std::ifstream file(path);
		if (!file) { std::cerr << "Cannot open " << path << '\n'; return false; }
		try { out = Json::parse(file); }
		catch (const Json::exception& e) { std::cerr << path << ": " << e.what() << '\n'; return false; }
		return true;
	}

	// fnmatch style: * any run, ? one character, [abc] / [!abc] one character of (not of) the set
	bool glob(const char* p, const char* s)
	{
		for (; *p; ++p, ++s)
		{
			if (*p == '*')
			{
				for (const char* t = s; ; ++t)
				{
					if (glob(p + 1, t)) return true;
					if (!*t) return false;
				}
			}
			if (!*s) return false;
			if (*p == '[')
			{
				const char* q = p + 1;
				const bool negate = *q == '!';
				if (negate) ++q;
				bool found = false;
				for (; *q && *q != ']'; ++q) if (*q == *s) found = true;
				if (!*q || found == negate) return false;
				p = q;
			}
			else if (*p != '?' && *p != *s) return false;
		}
		return !*s;
	}

	std::string text(const Json& value)
	{
		if (value.is_string()) return value.get<std::string>();
		if (value.is_array())
		{
			std::string out;
			for (const auto& v : value) out += (out.empty() ? "" : ",") + text(v);
			return out;
		}
		return value.dump();
	}

	// pattern: a glob on the text of the value, a list (any of), an object (every key), true/false, null
	bool matches(const Json& pattern, const Json& value)
	{
		if (pattern.is_array())
		{
			for (const auto& p : pattern) if (matches(p, value)) return true;
			return false;
		}
		if (pattern.is_object())
		{
			if (!value.is_object()) return false;
			for (const auto& [key, p] : pattern.items())
				if (!matches(p, value.contains(key) ? value[key] : Json())) return false;
			return true;
		}
		if (pattern.is_string()) return glob(pattern.get_ref<const std::string&>().c_str(), text(value).c_str());
		return pattern == value;
	}

	std::string str(const Json& c, const char* key) { return c.contains(key) && c[key].is_string() ? c[key].get<std::string>() : ""; }

	Request requestOf(const AirportConfig& cfg, const Json& airport, const Json& c)
	{
		Request req;
		req.waypoint = str(c, "waypoint");
		for (const auto& r : c.value("depRwys", Json::array())) req.depRwys.insert(r.get<std::string>());
		for (const auto& r : c.value("arrRwys", Json::array())) req.arrRwys.insert(r.get<std::string>());
		req.atcRwy = str(c, "atcRwy");
		const std::string engine = str(c, "engine"), kind = str(c, "aircraftKind");
		req.engine = engine.size() == 1 ? engine[0] : '?';
		req.aircraftKind = kind.size() == 1 ? kind[0] : '?';
		req.equipCheck = airport.value("equipCheck", true);
		req.equipment = str(c, "equipment");
		req.pbn = str(c, "pbn");
		req.wtc = str(c, "wtc");
		req.dest = str(c, "dest");
		if (c.contains("position") && c["position"].is_object())
			req.position = GeoPoint{ c["position"]["lat"].get<double>(), c["position"]["lon"].get<double>() };
		req.rules = cfg.customRules;
		if (c.contains("rules"))
			for (const auto& [name, on] : c["rules"].items()) req.rules[name] = on.get<bool>();
		req.mode = c.value("mode", std::string("default"));
		for (const auto& e : cfg.entries) req.available.insert(e.id);
		return req;
	}

	// "-" no SID, "EQUIP", else "SID RWY CLIMB"
	std::string expectText(const Json& expect)
	{
		if (expect.is_null()) return "-";
		if (expect.value("equip", false)) return "EQUIP";
		return expect.value("sid", std::string()) + " " + expect.value("rwy", std::string()) + " " + std::to_string(expect.value("climb", 0));
	}

	std::string resultText(const AirportConfig& cfg, const Result& r)
	{
		if (!r.entryId) return r.equipFailure ? "EQUIP" : "-";
		return cfg.entries.at(*r.entryId).designator + " " + r.rwy + " " + std::to_string(r.initialClimb);
	}

	std::string describe(const Json& c)
	{
		std::string rules;
		const Json states = c.value("rules", Json::object());
		for (const auto& [name, on] : states.items()) if (on.get<bool>()) rules += (rules.empty() ? "" : ",") + name;
		return str(c, "waypoint") + " dep=" + text(c.value("depRwys", Json::array())) + " arr=" + text(c.value("arrRwys", Json::array()))
			+ " eng=" + str(c, "engine") + " equip=" + str(c, "equipment") + " wtc=" + str(c, "wtc") + " dest=" + str(c, "dest")
			+ " pos=" + (c.contains("position") ? c["position"].dump() : "null") + " rules=" + (rules.empty() ? "-" : rules)
			+ " mode=" + c.value("mode", std::string("default"));
	}

	const char* equipReason = "EQUIP flag only: v2 flags EQUIP when an entry was dropped only for its equipment (spec 4.3)";
}

int main(int argc, char** argv)
{
	if (argc < 3 || argc > 4)
	{
		std::cerr << "Usage: configcases_test <config_v2.json> <cases.json> [accepted_differences.json]\n";
		return 2;
	}
	Json config, cases, accepted = Json::object();
	if (!loadJson(argv[1], config) || !loadJson(argv[2], cases) || (argc == 4 && !loadJson(argv[3], accepted))) return 2;

	// CONFIGCASES_ALL set: list every failure and every accepted case (EQUIP aside)
	const bool verbose = std::getenv("CONFIGCASES_ALL") != nullptr;
	bool allPassed = true;
	for (const auto& [icao, airportCases] : cases.items())
	{
		if (!config.contains(icao)) { std::cerr << icao << ": not in " << argv[1] << '\n'; return 2; }
		AirportConfig cfg;
		std::string error;
		if (!parseAirport(config[icao], icao, cfg, error)) { std::cerr << "Parse error: " << error << '\n'; return 2; }

		std::vector<const Json*> rules;
		for (const char* key : { "*", icao.c_str() })
			if (accepted.contains(key)) for (const auto& r : accepted[key]) rules.push_back(&r);

		int ok = 0, failed = 0;
		std::map<std::string, int> acceptedBy;
		std::vector<std::string> acceptedOrder;
		std::vector<std::string> failures, details;
		int index = 0;
		for (const auto& c : airportCases)
		{
			const std::string expect = expectText(c["expect"]);
			const std::string got = resultText(cfg, select(cfg, requestOf(cfg, config[icao], c)));
			++index;
			if (expect == got) { ++ok; continue; }

			std::string reason;
			if ((expect == "-" || expect == "EQUIP") && (got == "-" || got == "EQUIP")) reason = equipReason;
			else
			{
				Json subject = c;
				subject["expect"] = expect;
				subject["got"] = got;
				for (const Json* r : rules)
					if (matches((*r)["match"], subject)) { reason = (*r)["reason"].get<std::string>(); break; }
			}
			if (reason.empty())
			{
				++failed;
				failures.push_back("  #" + std::to_string(index - 1) + " " + describe(c) + " expect=" + expect + " got=" + got);
				continue;
			}
			if (!acceptedBy.contains(reason)) acceptedOrder.push_back(reason);
			++acceptedBy[reason];
			if (verbose && reason != equipReason)
				details.push_back("  ~#" + std::to_string(index - 1) + " " + describe(c) + " expect=" + expect + " got=" + got + " [" + reason.substr(0, 40) + "]");
		}

		int acceptedCount = 0;
		for (const auto& [reason, n] : acceptedBy) acceptedCount += n;
		std::cout << icao << " cases=" << airportCases.size() << " ok=" << ok << " accepted=" << acceptedCount << " failed=" << failed << '\n';
		for (const auto& reason : acceptedOrder) std::cout << "  accepted " << acceptedBy[reason] << ": " << reason << '\n';
		const size_t limit = verbose ? failures.size() : 40;
		const size_t shown = failures.size() < limit ? failures.size() : limit;
		for (size_t i = 0; i < shown; ++i) std::cout << failures[i] << '\n';
		if (failures.size() > shown) std::cout << "  ... " << failures.size() - shown << " more\n";
		for (const auto& line : details) std::cout << line << '\n';
		if (failed) allPassed = false;
	}
	return allPassed ? 0 : 1;
}
